exercises.solution:
function convexHull(points) {
  if (points.length < 3) return [...points];
  function cross(o, a, b) {
    return (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);
  }
  let start = points.reduce((min, p) => p.x < min.x || (p.x === min.x && p.y < min.y) ? p : min);
  const hull = [];
  let current = start;
  do {
    hull.push(current);
    let next = points[0];
    for (let i = 1; i < points.length; i++) {
      const c = cross(current, next, points[i]);
      if (next === current || c > 0 || (c === 0 && Math.hypot(points[i].x - current.x, points[i].y - current.y) > Math.hypot(next.x - current.x, next.y - current.y))) {
        next = points[i];
      }
    }
    current = next;
  } while (current !== start);
  return hull;
}

