exercises.solution:
function linearRegression(x, y) {
  const n = x.length;
  const meanX = x.reduce((a, b) => a + b, 0) / n;
  const meanY = y.reduce((a, b) => a + b, 0) / n;
  let num = 0, den = 0;
  for (let i = 0; i < n; i++) {
    const dx = x[i] - meanX;
    num += dx * (y[i] - meanY);
    den += dx * dx;
  }
  const slope = Math.round((num / den) * 10000) / 10000;
  const intercept = Math.round((meanY - slope * meanX) * 10000) / 10000;
  return { slope, intercept };
}

