exercises.solution:
function catalan(n) {
  // Using C(2n, n) / (n + 1)
  let result = 1;
  for (let i = 0; i < n; i++) {
    result = result * (2 * n - i) / (i + 1);
  }
  return Math.round(result / (n + 1));
}

