exercises.solution:
function countPartitions(n) {
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;
  for (let i = 1; i <= n; i++) {
    for (let j = i; j <= n; j++) {
      dp[j] += dp[j - i];
    }
  }
  return dp[n];
}

function generatePartitions(n) {
  const result = [];
  function backtrack(remaining, maxVal, current) {
    if (remaining === 0) {
      result.push([...current]);
      return;
    }
    for (let i = Math.min(remaining, maxVal); i >= 1; i--) {
      current.push(i);
      backtrack(remaining - i, i, current);
      current.pop();
    }
  }
  backtrack(n, n, []);
  return result;
}

