exercises.solution:
function dampedOscillator(mass, springConstant, dampingCoeff, x0, times) {
  const gamma = dampingCoeff / (2 * mass);
  const omega0sq = springConstant / mass;
  if (gamma * gamma >= omega0sq) {
    // Overdamped or critically damped
    return times.map(t => Math.round(x0 * Math.exp(-gamma * t) * 10000) / 10000);
  }
  const omegaD = Math.sqrt(omega0sq - gamma * gamma);
  return times.map(t => {
    const x = x0 * Math.exp(-gamma * t) * Math.cos(omegaD * t);
    return Math.round(x * 10000) / 10000;
  });
}

