  const c = 299792458;
  const beta = Math.round((velocity / c) * 1000000) / 1000000;
  const gamma = Math.round((1 / Math.sqrt(1 - beta * beta)) * 10000) / 10000;
  const timeDilation = gamma;
  const lengthContraction = Math.round((1 / gamma) * 10000) / 10000;
  const relativisticKE = Math.round((gamma - 1) * 1 * c * c);
  return { beta, gamma, timeDilation, lengthContraction, relativisticKE };
}

