exercises.solution:
function idealGas({ pressure, volume, moles, temperature }) {
  const R = 8.314;
  const r2 = v => Math.round(v * 100) / 100;
  if (pressure === undefined) return { pressure: r2(moles * R * temperature / volume) };
  if (volume === undefined) return { volume: r2(moles * R * temperature / pressure) };
  if (moles === undefined) return { moles: r2(pressure * volume / (R * temperature)) };
  return { temperature: r2(pressure * volume / (moles * R)) };
}

function gasWork(pressure, v1, v2) {
  return Math.round(pressure * (v2 - v1) * 100) / 100;
}

